def pad(inner,cls=""): return f"<div class='pad {cls}'>{inner}</div>"
def shot(img,l,t,w,cap=None):
    h=round(w*844/1440); c=f"<div class='cap' style='left:{l}px;top:{t+h+16}px'>{cap}</div>" if cap else ""
    return f"<div class='reveal shot' style='left:{l}px;top:{t}px;width:{w}px;--d:1'><img src='img/{img}.png' alt=''></div>{c}"
def cues(items): return "<ul class='cues reveal' style='--d:2'>"+''.join(f"<li><b>{k+1}</b>{x}</li>" for k,x in enumerate(items))+"</ul>"
