def lessons_body():
    def svg(inner,h=250): return f"<svg viewBox='0 0 500 {h}' width='500' height='{h}'>{inner}</svg>"
    T=lambda x,y,t,sz=26,c='#8B929C',a='start': f"<text x='{x}' y='{y}' text-anchor='{a}' {FF} font-size='{sz}' fill='{c}'>{t}</text>"
    cols=['#FF8A2A','#FFC24A','#E8EAED']
    def chunks(y,each):
        o=""
        for k in range(3):
            x=k*170
            o+=f"<rect x='{x}' y='{y}' width='160' height='62' rx='8' fill='#14171C' stroke='#262A31' stroke-width='2'/>"
            words=[0,1,2] if each=='all' else [k]
            for j,w in enumerate(words):
                wx=x+12+j*48 if each=='all' else x+56
                o+=f"<rect x='{wx}' y='{y+18}' width='38' height='26' rx='4' fill='{cols[w]}'/>"
        return o
    a=T(0,24,"Before: all words in every chunk")+chunks(40,'all')+T(0,150,"After: each chunk, its own words",26,'#E8EAED')+chunks(166,'own')
    b=T(0,24,"Example: 150 s of audio")+"<rect x='0' y='44' width='490' height='46' rx='6' fill='#8B929C'/>"+T(245,76,"one long track",26,'#0B0C0E','middle')+T(0,140,"Split into equal pieces ≤ 60 s",26,'#E8EAED')+''.join(f"<rect x='{k*166}' y='160' width='158' height='46' rx='6' fill='#FF8A2A'/>"+T(k*166+79,191,"50 s",26,'#0B0C0E','middle') for k in range(3))
    c=T(0,24,"The GPU stops after 7 idle min")+"<rect x='0' y='44' width='280' height='46' rx='6' fill='#262A31'/>"+T(140,76,"7 idle min",26,'#E8EAED','middle')+"<line x1='280' y1='30' x2='280' y2='120' stroke='#FF8A2A' stroke-width='3' stroke-dasharray='6 6'/>"+T(280,150,"video arrives just then",26,'#FF8A2A','middle')+"<rect x='286' y='44' width='204' height='46' rx='6' fill='#FFC24A'/>"+T(388,76,"waits 5–8 min",26,'#0B0C0E','middle')
    def card(n,title,sub,fig,fixed):
        return f"<div><p class='mono hl'>{n}</p><h2 style='font-size:38px;margin:10px 0 24px'>{title}</h2>{fig}<p style='font-size:28px;color:var(--muted);margin-top:22px;line-height:1.35'>{sub}</p></div>"
    cols_html="<div style='display:grid;grid-template-columns:repeat(3,1fr);gap:50px'>"+card("Fixed","Words repeated in every chunk","We replaced TRIBE v2's speech step.",svg(a,240),1)+card("Fixed","Long audio ran out of GPU memory","We split audio over 60 s into equal pieces.",svg(b,240),1)+card("Known limit","A video arrives as the GPU stops","The request restarts the GPU, so it waits a further 5–8 min.",svg(c,240),0)+"</div>"
    return A(1,140,300,cols_html,1640)
add("P1","",pad("<div class='fill'>"+R(0,"<h1>NeuroLens</h1>")+R(1,"<div class='tag hl' style='font-size:64px'>Watch a brain watch your video.</div>")+R(2,"<p class='mono' style='margin-top:48px'>Predicted brain response to video, second by second</p>")+R(3,"<p class='mono' style='margin-top:14px'>CS5224 Cloud Computing · Final presentation · Dylan Chan · Xin Wei Chong · Kelvin Low · Joshua Lum · Brandon Tan</p>")+"</div>","title")+CURVE,
"Good afternoon, everyone. We're team NeuroLens, and we'll show you a cloud service that predicts how a viewer's brain responds to a video, second by second, without putting anyone in a scanner. I'll cover the business need and the brain model behind it. Then we'll cover the business model, a live demo, how we evaluated it, and the ethics and next steps.","title")
add("P1","Problem",pad("<div class='fill'><div style='display:grid;grid-template-columns:660px 1fr;gap:70px;align-items:center'>"+R(0,"<div class='big' style='font-size:250px'>$10k+</div><p class='sub' style='margin-top:30px;font-size:40px'>to test one ad on a brain scanner</p>")+R(1,"<div class='rows'><div class='r'><span>fMRI study</span><span>$10 – 15k</span><span>2–4 weeks</span></div><div class='r us'><span>NeuroLens</span><span>$1.00</span><span>≈ 7 min</span></div></div>")+"</div>"+"</div>"),
"Let's start with a simple question: how do you know whether an ad works? Surveys are the usual answer, but people are bad at explaining their own reactions. Brain scans do better, because they show how viewers really react, second by second. The catch is the price. An fMRI study costs ten to fifteen thousand dollars per advert and takes two to four weeks. NeuroLens costs one dollar for a thirty-second video and takes about seven minutes, which we measured. That gap is the reason this project exists.")
add("P1","Why now",pad("<div style='display:grid;grid-template-columns:960px 1fr;gap:40px;flex:1;align-items:center'><div>"+R(0,"<h1 style='font-size:80px'>Dozens of cuts.<br><em>No way to judge them.</em></h1>")+R(1,"<p class='sub'>Generative tools made production cheap. The feed made every second count.</p>")+"</div>"+R(2,"<svg viewBox='0 0 800 520' width='800' height='520'><line x1='0' y1='290' x2='800' y2='290' stroke='#262A31' stroke-width='2' stroke-dasharray='8 12'/><path class='draw' pathLength='1' stroke='#FF8A2A' stroke-width='6' d='M0 120 C100 110 170 100 250 140 S340 170 390 290 S480 450 540 420 S650 300 720 350 S780 400 800 450'/><circle cx='505' cy='430' r='26' fill='none' stroke='#FFC24A' stroke-width='4'/><text x='440' y='500' fill='#FFC24A' font-family='JetBrains Mono' font-size='26'>where did we lose them?</text><text x='0' y='40' fill='#8B929C' font-family='JetBrains Mono' font-size='24'>VIEWER ATTENTION (ILLUSTRATIVE)</text></svg>")+"</div>"),
"And the gap is getting wider. Generative tools like Runway, Sora and CapCut mean a small team can now produce dozens of versions of an ad quickly, and every version has to be judged. Viewers watch in fast-scrolling feeds, where one swipe ends the ad, so you can lose someone at a quiet stretch, like this dip. Creators ask: where exactly did I lose them, and which version is stronger?")
add("P1","Industry",pad("<div class='fill'>"+R(0,"<h1>What already exists: <em>measured, filmed or guessed.</em></h1>")+R(1,"<div class='rows' style='margin-top:20px'><div class='r' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>Physical fMRI study<br><small style='font-size:24px;color:var(--muted);font-weight:400'>university and research labs</small></span><span>$10,000 – $15,000</span><span>2–4 weeks</span></div><div class='r' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>Facial coding<br><small style='font-size:24px;color:var(--muted);font-weight:400'>Realeyes, iMotions webcam studies</small></span><span>$850 – $4,000</span><span>3–5 days</span></div><div class='r' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>AI attention maps<br><small style='font-size:24px;color:var(--muted);font-weight:400'>Neurons, Dragonfly AI</small></span><span>$500 – $1,500 / mo</span><span>sub-minute</span></div><div class='r us' style='grid-template-columns:600px 400px 1fr;font-size:32px;padding:12px 0'><span>NeuroLens<br><small style='font-size:24px;color:var(--muted);font-weight:400'>predicted brain response</small></span><span>$1.00</span><span>≈ 7 min</span></div></div>")+"<div class='cols c3' style='gap:60px;margin-top:24px'>"+R(2,"<p class='mono hl'>Our difference</p><h2 style='font-size:38px'>A brain response, not a gaze or a face</h2>")+R(3,"<p class='mono hl'>&nbsp;</p><h2 style='font-size:38px'>Per second, with a no-sound pass</h2>")+R(4,"<p class='mono hl'>&nbsp;</p><h2 style='font-size:38px'>Compare any two cuts directly</h2>")+"</div>"+"</div>"),
"So what already exists? Three groups. First, physical fMRI studies: real brain scans, but expensive and slow. Second, facial coding, from vendors like Realeyes and iMotions, which read viewers' faces from a webcam. It is cheaper, but it reads faces, not brains. Third, AI attention tools such as Neurons and Dragonfly AI, which predict from the creative itself where eyes will land. They are fast, but they show what is noticed, not how a brain responds. NeuroLens sits in the gap: a predicted brain response for every second, with a second pass that removes the sound, for a dollar.")
add("P1","TRIBE v2",pad(R(0,"<h1>Under the hood: <em>TRIBE v2.</em></h1>"))+A(1,140,330,tribe_svg()),
"The model underneath is TRIBE v2, from Meta's AI research lab. It was trained on over a thousand hours of real fMRI from 720 people. It takes three inputs, frames, sound and words, through four models: V-JEPA 2 watches, Wav2Vec-BERT listens, and WhisperX and LLaMA 3.2 handle the speech. Out comes predicted activity at twenty thousand four hundred and eighty-four points on the cortex, every second. In Meta's paper it handles new videos and new people several times better than older models.")
add("P1","Signals",pad(R(0,"<h1>Seven signals, <em>three questions.</em></h1>"))+A(1,140,330,"<img src='img/signals.png' alt='' style='width:1640px;display:block;border:1px solid var(--line);border-radius:4px'>")+A(2,147,770,"<p class='mono hl'>Seeing</p><p style='font-size:34px;margin-top:8px'>faces · bodies · scenes · visual</p>",520)+A(2,704,770,"<p class='mono hl'>Hearing</p><p style='font-size:34px;margin-top:8px'>sound</p>",520)+A(2,1261,770,"<p class='mono hl'>Understanding</p><p style='font-size:34px;margin-top:8px'>speech · social</p>",520)+A(3,140,900,"<div style='height:10px;border-radius:5px;background:linear-gradient(90deg,#2a3a55,#2a2f38 45%,#6b3a12 60%,#FF8A2A 80%,#FFC24A)'></div><div style='display:flex;justify-content:space-between;margin-top:12px' class='mono'><span>below typical</span><span>0 = typical film &amp; TV viewing</span><span>above typical</span></div>",1640),
"We turn those cortex points into seven signals in three groups, using brain areas from the Glasser atlas. Seeing covers faces, bodies, scenes and visual areas. Hearing covers sound. Understanding covers speech and social cues. This is a crop of our live site. The scale is the same on all three, and zero means typical film and TV viewing, so any two videos compare directly. A second pass with the sound removed shows what the soundtrack adds. Hold on to these three groups, because you'll see them move in the demo. Over to my teammate for the business model.")
add("P2","Business model",pad(R(0,"<h1>Pay as you go. <em>Credit, not cards.</em></h1>"))+bm_body(),
"Thanks. NeuroLens is for independent creators and small agencies who make many AI-generated versions of an advert and need to pick one before paying for media. It's pay as you go: one dollar for each started thirty seconds, from prepaid credit. New users get ten dollars once their access request is approved, enough for ten videos. Why credit, not a card per video? A card fee of about 2.9 percent plus thirty cents takes about a third of a one-dollar charge, but only about four percent of a twenty-dollar pack. One caveat: in our proof of concept no one pays real money, and TRIBE v2 is non-commercial, so this is the model we would use if Meta approved a licence.")
add("P2","Unit economics",pad(R(0,"<h1>What one analysis <em>costs us.</em></h1>"))+econ_body(),
"What does one analysis cost us? About 393 seconds of GPU time on an L4 at one dollar twenty-two an hour: thirteen cents. Each session also pays for one GPU start-up and seven idle minutes, shared across its videos. With three videos in a session, a video costs us twenty-three cents. With thirty, fourteen cents. Against a one-dollar price, that is a gross margin of seventy-seven to eighty-six percent, plus about five dollars a month fixed. We hoped for ten cents on Spot GPUs, but Spot capacity was not available.","data")
add("P2","Why cloud",pad(R(0,"<h1>Why cloud, <em>not a workstation?</em></h1>"))+why_body(),
"So why a cloud service and not a workstation? A machine with an RTX 4090 costs about five thousand dollars up front. Spread over three years with idle power, that is about one hundred fifty-nine dollars a month before a single video is analysed. Ad testing comes in bursts: an agency may run twenty jobs in an editing sprint, then nothing for days, so that GPU sits idle over eighty percent of the time. The cloud remedy is to rent a GPU only when a video is waiting and stop it after seven idle minutes. Idle, the service costs about five dollars a month. Keeping one L4 warm around the clock would cost about eight hundred ninety.","data")
add("P2","SaaS vs on-premise",pad(R(0,"<h1>Cloud is cheaper below about <em>670 videos a month.</em></h1>")+"<div class='chart reveal fill' data-viz='break' style='--d:1'><div class='vz'></div></div>"),
"So where is the break-even? The owned machine is flat at about one hundred fifty-nine dollars a month, and costs almost nothing per video, about a third of a cent of electricity. AWS has about five dollars a month fixed, but twenty-three cents a video. The lines cross at 670 videos a month. Below that, renting is cheaper. Above it, owning wins: at a thousand videos a month over three years, about fifty-eight hundred dollars owned against eighty-five hundred on AWS. Over to my colleague, who'll show it live.","data")
add("P3","Demo",dtitle("Live demo: sign in, upload, explore")+"<div class='reveal shot' style='left:140px;top:220px;width:1290px;--d:1'><a href='https://df6girqyykyfa.cloudfront.net' target='_blank' rel='noopener'><img src='img/result.png' alt='NeuroLens result page'></a></div><div class='cap' style='left:140px;top:992px'>Click the picture to open the live site · df6girqyykyfa.cloudfront.net</div>"+cues(["Upload: price first","Peak, dip, no-sound toggle","Seeing · hearing · understanding","AI report, compare, bad file"]),
"Thanks. Now let me show you the real thing. This is the live site, running on AWS, and the picture on the slide is a link to it. I'll sign in with Google; email works too. My credit balance is at the top. I'll pick a thirty-second clip. Before anything is sent, the app tells me exactly what it will cost: one dollar for each started thirty seconds. I get a short window to cancel, because GPU time costs real money, and then I confirm. The file goes straight from my browser to cloud storage, and the job moves through stages I can watch: checking the file, waiting for a GPU, and analysing. We warmed a GPU up before this session, but even warm, a thirty-second clip takes about seven minutes, so I'll leave it running and open a finished sample: the thirty-second CeraVe ad, one of our free samples. On the left, the video plays with a 3D brain synced to it, and you can drag the brain to rotate it. The orange line is the overall predicted response of an average viewer, compared with typical viewing. Around second six, when the actor holds up the product and looks at the camera, it peaks, and the label says well above typical. The orange dots mark moments the system flags as notable, and the strip of frames underneath shows what was on screen. Click anywhere on the chart and the video jumps to that moment. Now the three groups we just met. Seeing, hearing and understanding sit on the same scale, so you can see which one drives the peak. Here it is seeing and hearing together, the face and the voice, and you can open each group to see its parts. Towards the end the line falls below typical, on the closing product card, with no face and no speech. The toggle shows the same video without sound. That is the second pass I described, and the page tells us forty-six percent of the response comes from the soundtrack. Numbers are useful, but creators want advice. The Report tab is written by an AI model that reads the brain data and the video frames together. It lists strengths and improvements, then specific moments, with the second each one starts, what is on screen, what the brain is doing, and what to change. The Compare tab puts two videos side by side: here, the thirty-second cut against the longer cut of the same ad. The verdict says the short cut's direct opening gives it an early edge, but the two finish close. You can download the result as a CSV, or the report as a PDF. One last thing people ask: what if someone uploads something that is not a video? I'll try a text file renamed to MP4. It is rejected within seconds, before any GPU starts, and nothing is charged. Over to my colleague, who will show how we evaluated it.","demo")
add("P4","Validation",pad(R(0,"<h1>Can we <em>trust it?</em></h1>"))+val_body(),
"Thanks. Now evaluation, organised around the questions a user would ask. First: can we trust it? Two things we checked ourselves. The same clip through the same code on our RTX 4090 and on AWS gives the same result: across all eleven series, no value differs by more than 0.005. And 77 of 80 automated refund tests refunded a failed job exactly once; the other three stopped on a GPU-library error during setup. What we did not check: the model's accuracy is Meta's result, and we did not test whether a higher response means more views or sales, so we make no such claim.","data")
add("P4","Wait",pad(R(0,"<h1>How long will a user <em>wait?</em></h1>"))+wait_body(),
"Next: how long will a user wait? Same thirty-second clip each time. On our own RTX 4090 it takes 128 seconds. On AWS with the GPU already warm it takes 415: about three seconds to upload, nineteen waiting in the queue, and the rest analysing. After a quiet spell, the first video takes about 779 seconds, about thirteen minutes, because a GPU has to start: our two cold starts waited 452 and 277 seconds. That is the price of paying for a GPU only when needed.","data")
add("P4","Scaling",pad(R(0,"<h1>Five people at once: <em>they wait in line.</em></h1>")+R(1,"<p class='sub' style='margin-top:14px;font-size:32px'>Five uploads at the same moment. One GPU runs one job at a time.</p>"))+A(2,140,360,queue_svg(),1640)+A(3,140,900,"<p class='mono'>Nothing was dropped. The AWS run got an A10G, and its first job appears to have restarted once.</p>",1640),
"Next: what if several people use it at once? We sent five uploads at the same moment. Both setups run one job at a time, so everyone queues. On AWS each block is one person's job, about 323 seconds each, and the last finished after 2,145 seconds, about thirty-six minutes. On our own machine all five were done in 575 seconds. Nothing was dropped. Serving more at once would need a GPU quota increase.","data")
add("P4","Usability",pad(R(0,"<h1>Can people <em>use it?</em></h1>"))+usab_body(),
"Next, can people use it? Eleven people tried NeuroLens at our booth, a small formative test, and answered the System Usability Scale. The mean is 71.6 out of 100, and five of the eleven reached eighty, which is usually read as very good. Scores split: six people at 77.5 or more, five between 47.5 and 55. One respondent gave a four to every item, which scores as fifty, so the low group may understate usability. Two things confused people: a muted video in the Compare tab, and what the brain regions mean. Both are small fixes. Caveat: eight of the eleven were students, not our target users.","data")
add("P4","Value",pad(R(0,"<h1>Is it <em>worth using?</em></h1>"))+value_body(),
"Is it worth using? Nine of eleven, 82 percent, said it showed them something they had not noticed. Seven, 64 percent, would pay one dollar for a thirty-second video, and two more might. The chart scored 4.3 out of 5 for understanding the video, and 4.1 for use when editing. Trust was lower, at 3.7: three of the four who would not pay, or were unsure, doubted the accuracy. One person said it helps me improve my video easily and update the scenes to make it more engaging. That is why we are upfront about what we did not validate. Over to my colleague for what we learned and where this goes.","data")
add("P5","Lessons",pad(R(0,"<h1>What broke, <em>and what we did.</em></h1>"))+lessons_body(),
"Thanks. Let us look back at what we learned. Three things broke. TRIBE v2's speech step attached the whole transcript to every audio chunk, so words repeated; we replaced it so each chunk keeps its own words. GPU memory grows with audio length, so we split audio over sixty seconds into equal pieces. And an edge case we have not fixed: a video arriving just as the seven idle minutes end can still stop the GPU, so it waits five to eight more minutes.","data")
add("P5","Limits and ethics",pad(R(0,"<h1>What it claims, <em>and what it doesn't.</em></h1>")+"<div class='cols c3' style='margin-top:90px;gap:60px'>"+R(1,"<p class='mono hl' style='margin-bottom:18px'>What it is</p><ul class='list'><li>An average viewer's brain response</li><li>One scale for every video</li></ul>")+R(2,"<p class='mono' style='margin-bottom:18px'>What it isn't</p><ul class='list no'><li>A prediction of views or sales</li><li>Instant: first video ≈ 6 min</li><li>Tested on creators (8 of 11 were students)</li></ul>")+R(3,"<p class='mono hl' style='margin-bottom:18px'>Ethics</p><ul class='list'><li>Non-commercial licence (CC BY-NC)</li><li>No one scanned or profiled</li><li>Anonymous, consented survey</li></ul>")+"</div>"),
"Next, limits and ethics. NeuroLens gives an average viewer's predicted brain response, a virtual pre-test for editing. It is not a prediction of views or sales, which we did not test. It is not instant, since a cold start waits about six minutes. And it has not been tested on our target users, as eight of our eleven testers were students. On ethics: TRIBE v2 is non-commercial, so a paid launch needs a licence. No real person is scanned or profiled. Still, a tool that shows what holds attention could be used to hold it at any cost, so we position it for checking edits, not manipulating people. Our survey was anonymous and consented, and our report declares how we used AI.")
add("P5","Where next",pad(R(0,"<h1>Where next: <em>scaling up.</em></h1>"))+A(1,140,290,gpu_chart_svg())+A(2,1180,300,"<div class='big' style='font-size:130px'>26 / 26</div><p style='font-size:30px;color:var(--muted);margin-top:10px'>Spot launches failed for lack of capacity</p><div class='big' style='font-size:130px;margin-top:50px'>19.9 GB</div><p style='font-size:30px;color:var(--muted);margin-top:10px'>peak GPU memory: a 24 GB card fits</p>",600)+A(3,140,850,"<p class='sub' style='font-size:32px;margin-top:0'>An EC2 GPU pool: <span class='hl'>$0.10 – $0.20</span> a video, about $70 more a month. It pays off above about 1,000 videos a month. Estimates, not built.</p>",1640),
"Where does this go next? Our proof of concept runs one GPU at a time. We tested a larger design with CPU instances, then moved the GPU to SageMaker after three findings. Spot did not deliver: all twenty-six launches failed for lack of capacity. A smaller GPU is enough, since the model peaked at about twenty gigabytes. And the GPU sets the speed: an L40S finished a 119 second clip in 491 seconds, against 1,540 on an L4. The larger design adds about seventy dollars a month of fixed cost, so it pays off above roughly a thousand videos a month. At today's volume SageMaker is the better choice, and the first step is to build it and measure its start-up time.","data")
add("P5","Conclusion",pad(R(0,"<h1>A $10,000 brain study,<br><em>in 7 minutes for $1.</em></h1>"))+A(1,140,470,"<div style='display:grid;grid-template-columns:repeat(4,1fr);gap:40px'>"+"".join(f"<div><div class='big' style='font-size:96px'>{a}</div><p style='font-size:28px;color:var(--muted);margin-top:12px'>{b}</p></div>" for a,b in [("$1.00","per 30 s video"),("≈ 7 min","to a result, GPU warm"),("670","videos a month: break-even vs owning"),("≈ 6 min","first video after a quiet spell")])+"</div>",1640)+"<div class='flow reveal' style='grid-template-columns:repeat(3,1fr);position:absolute;left:140px;top:760px;width:1640px;--d:3'><div class='n'><i>Next</i><b>Licence</b><span>CC BY-NC: a paid launch needs one.</span></div><div class='n'><i>Next</i><b>Scale</b><span>A GPU pool that grows with the queue.</span></div><div class='n'><i>Next</i><b>Polish</b><span>A sound control on each player, a note on each signal.</span></div></div>",
"To wrap up. NeuroLens returns a viewer's predicted brain response in about seven minutes for about one dollar, where an fMRI study costs ten thousand dollars or more and takes weeks. Below 670 videos a month, renting a GPU costs less than owning one. The trade-off is the wait: after a quiet spell, the first video waits about six minutes. The model predicts an average viewer, not views or sales. Next: a commercial licence, the scaled-up design once built and measured, and small fixes from our usability study. Thank you for listening, and we'd be happy to take your questions.")
add("P5","Q&amp;A",pad("<div class='fill'>"+R(0,"<h1 style='font-size:140px'>Thank you.<br><em>Questions?</em></h1>")+R(1,"<p class='hl2' style='font-size:52px;margin-top:70px;font-weight:500'>df6girqyykyfa.cloudfront.net</p>")+R(2,"<p class='mono' style='margin-top:18px'>Code · github.com/kelvinlowhm86/neurolens</p>")+"</div>")+A(1,1050,200,"<img src='img/steps.jpg' alt='' style='width:730px;display:block;border:1px solid var(--line);border-radius:4px'>",730)+A(2,1050,775,"<p style='font-size:44px;font-weight:600;line-height:1.2'>Thanks for supporting us <span class='hl'>at STePS!</span></p>",730),
"Thank you for supporting us at STePS. Open for questions. Keep answers ready on: why this model and its licence, what the prediction does and does not mean, the cloud design and the cold-start wait, why SageMaker rather than Spot or our own GPU pool (the Where next slide), how refunds work, and what the experiments showed.","title")
# ---------------- build ----------------
esc=lambda x: html.escape(x,quote=True)
words=lambda s: len(re.findall(r"\S+",s))
N=len(S); out=[]; per={}
for i,(p,l,b,sc,k) in enumerate(S,1):
    w=words(sc); sec=round(w/WPM*60); per.setdefault(p,[0,0]); per[p][0]+=w; per[p][1]+=sec
    kick=f"<div class='kicker'>{i:02d} · {l}</div>" if l else ""
    out.append(f"<section class='slide {k}'>{kick}<div class='who'>{SECT.get(p,'')}</div>{b}<div class='pgn'>{i}/{N}</div><template><span class='m'>{p} · {w} words · ~{sec}s</span> {esc(sc)}</template></section>")
open('Slides.html','w').write(open('template.html').read().replace('%%SLIDES%%','\n'.join(out)).replace('%%DATA%%',json.dumps(DATA)))
md=["# NeuroLens: presentation script\n",f"Target: 450-500 words per presenter (~{WPM} words/min). Slides 1-{N-1} are the talk, {N} is Q&A. `[TBD]` = fill from the usability study (edit DATA in gen.py for charts). Numbers come from the final report.\n"]
cur=None
for i,(p,l,b,sc,k) in enumerate(S,1):
    if p!=cur: md.append(f"\n## {p}{' · '+SECT[p] if p in SECT else ''}: {per[p][0]} words, ~{per[p][1]//60}:{per[p][1]%60:02d}\n"); cur=p
    md.append(f"**Slide {i}: {l or 'Title'}** ({words(sc)} words)\n\n> {sc}\n")
tw=sum(v[0] for k,v in per.items() if k!='ALL'); ts=sum(v[1] for k,v in per.items() if k!='ALL')
md.append(f"\n**Total: {tw} words, ~{ts//60}:{ts%60:02d}**\n"); open('Script.md','w').write('\n'.join(md))
for p,v in per.items(): print(p,v[0],'words',v[1],'s')
print('total',tw,ts//60,ts%60)
